import type { HardhatEthersSigner } from '@nomicfoundation/hardhat-ethers/types';
import { toBufferBE } from 'bigint-buffer';
import type { Signer, TypedDataDomain } from 'ethers';
import path from 'node:path';

import { getRequiredEnvVar } from '../tasks/env.js';
import type { Counter } from '../typechain-types/index.js';
import { ethers, isInProcessNetwork } from './hardhat.js';
import type { ClearValues, FhevmInstance } from './legacyRelayerSdk/types.js';
import { isEuintFheTypeId } from './legacyRelayerSdk/types.js';
import { getSigners } from './signers.js';

// `.env` file generated by the deploy tasks, holding the host contract addresses. Absolute path, resolved from this
// file's location so it does not depend on the directory the process runs from.
export const HOST_ADDRESSES_ENV_PATH = path.resolve(import.meta.dirname, '../fhevmTemp/addresses/.env.host');

// EIP-712 domain of the gateway Decryption contract, from the CHAIN_ID_GATEWAY and DECRYPTION_ADDRESS env variables.
export function getDecryptionEip712Domain(): TypedDataDomain {
  return {
    name: 'Decryption',
    version: '1',
    chainId: getRequiredEnvVar('CHAIN_ID_GATEWAY'),
    verifyingContract: getRequiredEnvVar('DECRYPTION_ADDRESS'),
  };
}

export function toHexString(bytes: Uint8Array, with0x = false): string {
  return `${with0x ? '0x' : ''}${bytes.reduce((str, byte) => str + byte.toString(16).padStart(2, '0'), '')}`;
}

export function fromHexString(hexString: string): Uint8Array {
  const arr = hexString.replace(/^(0x)/, '').match(/.{1,2}/g);
  if (!arr) return new Uint8Array();
  return Uint8Array.from(arr.map((byte) => parseInt(byte, 16)));
}

// Returns the bytes as lowercase hex, 2 chars per byte, without a `0x` prefix (e.g. [0, 255] -> "00ff").
export function uint8ArrayToHexStringNo0x(uint8Array: Uint8Array): string {
  return Array.from(uint8Array)
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

// Returns the number as lowercase hex, padded to an even length, without a `0x` prefix (e.g. 1 -> "01").
export function numberToHexNo0x(num: number): string {
  if (!Number.isInteger(num) || num < 0) {
    throw new Error(`Expected a non-negative integer, got ${num}`);
  }
  const hex = num.toString(16);
  return hex.length % 2 === 1 ? '0' + hex : hex;
}

export function sum(arr: number[]): number {
  return arr.reduce((acc, val) => acc + val, 0);
}

export async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Throws if `signer` is not an object whose `address` is one of the hardhat signers.
// Returns the matching HardhatEthersSigner (an async function cannot be an `asserts` type guard).
export async function checkIsHardhatSigner(signer: unknown): Promise<HardhatEthersSigner> {
  const address =
    typeof signer === 'object' && signer !== null && 'address' in signer && typeof signer.address === 'string'
      ? signer.address
      : undefined;
  if (address === undefined || !ethers.isAddress(address)) {
    throw new Error(`Expected a signer with a valid address, got ${String(signer)}`);
  }

  const signers: HardhatEthersSigner[] = await ethers.getSigners();
  const hardhatSigner = signers.find((s) => s.address.toLowerCase() === address.toLowerCase());
  if (hardhatSigner === undefined) {
    throw new Error(
      `The provided address (${address}) is not the address of a valid hardhat signer.
      Please use addresses listed via the 'npx hardhat get-accounts --network hardhat' command.`,
    );
  }
  return hardhatSigner;
}

function toError(err: unknown): Error {
  return err instanceof Error ? err : new Error(String(err));
}

export function waitForBlock(blockNumber: bigint | number): Promise<number | bigint> {
  if (isInProcessNetwork) {
    return new Promise((resolve, reject) => {
      const intervalId = setInterval(() => {
        ethers.provider.getBlockNumber().then(
          (currentBlock) => {
            if (BigInt(currentBlock) >= blockNumber) {
              clearInterval(intervalId);
              resolve(currentBlock);
            }
          },
          (error: unknown) => {
            clearInterval(intervalId);
            reject(toError(error));
          },
        );
      }, 50); // Check every 50 milliseconds
    });
  } else {
    return new Promise((resolve, reject) => {
      const rejectWithError = (err: unknown): void => {
        reject(toError(err));
      };
      const waitBlock = (currentBlock: number): void => {
        if (blockNumber <= BigInt(currentBlock)) {
          ethers.provider.off('block', waitBlock).then(() => {
            resolve(blockNumber);
          }, rejectWithError);
        }
      };
      ethers.provider.on('block', waitBlock).catch(rejectWithError);
    });
  }
}

export async function waitNBlocks(nBlocks: number): Promise<void> {
  const currentBlock = await ethers.provider.getBlockNumber();
  if (isInProcessNetwork) {
    await _produceDummyTransactions(nBlocks);
  }
  await waitForBlock(currentBlock + nBlocks);
}

export async function waitForBalance(address: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const rejectWithError = (err: unknown): void => {
      reject(toError(err));
    };
    const checkBalance = (): void => {
      ethers.provider.getBalance(address).then((balance) => {
        if (balance > 0) {
          ethers.provider.off('block', checkBalance).then(() => {
            resolve();
          }, rejectWithError);
        }
      }, rejectWithError);
    };
    ethers.provider.on('block', checkBalance).catch(rejectWithError);
  });
}

async function _produceDummyTransactions(blockCount: number): Promise<void> {
  const contract = await _deployCounterContract();
  let counter = blockCount;
  while (counter > 0) {
    counter--;
    const tx = await contract.increment();
    await tx.wait();
  }
}

async function _deployCounterContract(): Promise<Counter> {
  const signers = await getSigners();

  const contractFactory = await ethers.getContractFactory('Counter');
  const contract = await contractFactory.connect(signers.dave).deploy();
  await contract.waitForDeployment();

  return contract;
}

export async function mineNBlocks(n: number): Promise<void> {
  for (let index = 0; index < n; index++) {
    await ethers.provider.send('evm_mine');
  }
}

// Takes a snapshot of the hardhat network state and returns its id (a hex string such as "0x1").
export async function evmSnapshot(): Promise<string> {
  const snapshotId: unknown = await ethers.provider.send('evm_snapshot', []);
  if (typeof snapshotId !== 'string') {
    throw new Error(`evm_snapshot returned a non-string snapshot id: ${String(snapshotId)}`);
  }
  return snapshotId;
}

export function bigIntToBytes64(value: bigint): Uint8Array {
  return new Uint8Array(toBufferBE(value, 64));
}

export function bigIntToBytes128(value: bigint): Uint8Array {
  return new Uint8Array(toBufferBE(value, 128));
}

export function bigIntToBytes256(value: bigint): Uint8Array {
  return new Uint8Array(toBufferBE(value, 256));
}

// Throws if handle is not a 32-byte handle (hex string or bytes) whose FheTypeId is a euintxxx
function _assertIsEuintHandle(handle: string | Uint8Array): void {
  if (typeof handle === 'string' ? !ethers.isHexString(handle, 32) : handle.length !== 32) {
    const shown = typeof handle === 'string' ? handle : ethers.hexlify(handle);
    throw new Error(`Invalid handle ${shown}, expected 32 bytes`);
  }
  const fheTypeId = ethers.getBytes(handle)[30];
  if (!isEuintFheTypeId(fheTypeId)) {
    throw new Error(`Handle ${ethers.hexlify(handle)} is not a euint (FheTypeId=${fheTypeId})`);
  }
}

export const userDecryptSingleEuint = async (
  handle: string | Uint8Array,
  contractAddress: string,
  instance: FhevmInstance,
  signer: Signer,
  privateKey: string,
  publicKey: string,
): Promise<bigint> => {
  _assertIsEuintHandle(handle);

  const ctHandleContractPairs = [
    {
      handle: handle,
      contractAddress: contractAddress,
    },
  ];
  const startTimeStamp = Math.floor(Date.now() / 1000).toString();
  const durationDays = '10'; // String for consistency
  const contractAddresses = [contractAddress];

  // Use the new createEIP712 function
  const eip712 = instance.createEIP712(publicKey, contractAddresses, startTimeStamp, durationDays);

  // Update the signing to match the new primaryType
  const signature = await signer.signTypedData(
    eip712.domain,
    { UserDecryptRequestVerification: eip712.types.UserDecryptRequestVerification },
    eip712.message,
  );

  const signerAddress = await signer.getAddress();

  const decryptedValues: ClearValues = await instance.userDecrypt(
    ctHandleContractPairs,
    privateKey,
    publicKey,
    signature.replace('0x', ''),
    contractAddresses,
    signerAddress,
    startTimeStamp,
    durationDays,
  );

  const entries = Object.entries(decryptedValues);
  if (entries.length !== 1) {
    throw new Error(`Expected a single decrypted value, got ${entries.length}`);
  }

  const [decryptedHandle, decryptedValue] = entries[0];
  // ethers.hexlify returns lowercase 0x-prefixed hex for both strings and bytes
  const handleHex = ethers.hexlify(handle);
  if (ethers.hexlify(decryptedHandle) !== handleHex) {
    throw new Error(`Expected decrypted value for handle ${handleHex}, got ${decryptedHandle}`);
  }
  if (typeof decryptedValue !== 'bigint') {
    throw new Error(`Expected a bigint decrypted value, got ${typeof decryptedValue}`);
  }

  return decryptedValue;
};
